import fs from 'node:fs';import crypto from 'node:crypto';import * as T from 'three';import {GLTFExporter} from 'three/addons/exporters/GLTFExporter.js';import {mergeGeometries} from 'three/addons/utils/BufferGeometryUtils.js';import {buildReferenceRover} from './reference-rover.js';
class FileReader{readAsArrayBuffer(blob){blob.arrayBuffer().then(b=>{this.result=b;this.onloadend?.()})}}globalThis.FileReader=FileReader;const out=new URL('./output/',import.meta.url),reports=[];
async function save(root,id,source,wheels=[],radius=0){
 root.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(root,true);root.position.y-=bounds.min.y;root.updateMatrixWorld(true);
 const result=new T.Group();result.name=id;const wheelSets=wheels.map(w=>new Set([w,...(()=>{let a=[];w.traverse(o=>a.push(o));return a})()]));
 const buckets=new Map();let meshes=0,vertices=0;
 root.traverse(o=>{if(!o.isMesh)return;meshes++;let geo=o.geometry.clone();geo.applyMatrix4(o.matrixWorld);for(const a of Object.keys(geo.attributes))if(!['position','normal'].includes(a))geo.deleteAttribute(a);if(!geo.attributes.normal)geo.computeVertexNormals();if(!geo.index)geo.setIndex(Array.from({length:geo.attributes.position.count},(_,i)=>i));vertices+=geo.attributes.position.count;for(const n of geo.attributes.position.array)if(!Number.isFinite(n))throw Error(id+' contains nonfinite geometry');
 const material=Array.isArray(o.material)?o.material[0]:o.material;const wi=wheelSets.findIndex(s=>s.has(o));const key=[wi,material.color?.getHex()||0,material.metalness||0,material.roughness??.6,material.opacity,material.emissive?.getHex(),material.emissiveIntensity].join(':');if(!buckets.has(key))buckets.set(key,{wi,geos:[],mat:material.clone()});buckets.get(key).geos.push(geo);
 });
 const pivots=wheels.map((w,i)=>{const box=new T.Box3().setFromObject(w,true);const p=new T.Group();p.position.copy(box.getCenter(new T.Vector3()));p.name='drive-wheel-'+i;p.userData={rollingRadius:radius};result.add(p);return p});
 for(const {wi,geos,mat} of buckets.values()){const g=mergeGeometries(geos,false);if(!g)throw Error('Merge failure');if(wi>=0)g.translate(...pivots[wi].position.clone().negate().toArray());const mesh=new T.Mesh(g,mat);mesh.castShadow=mesh.receiveShadow=true;(wi>=0?pivots[wi]:result).add(mesh)}
 const bytes=await new GLTFExporter().parseAsync(result,{binary:true,onlyVisible:true});fs.writeFileSync(new URL(id+'.glb',out),Buffer.from(bytes));const size=new T.Box3().setFromObject(result,true).getSize(new T.Vector3()).toArray();const report={id,source,meshes,vertices,drawCalls:buckets.size,wheels:pivots.length,dimensions_m:size,bytes:bytes.byteLength,sha256:crypto.createHash('sha256').update(Buffer.from(bytes)).digest('hex')};reports.push(report);console.log(JSON.stringify(report));
}
const model=buildReferenceRover(),wheels=[];model.traverse(o=>{if(o.userData.rollingRadius)wheels.push(o)});await save(model,'reference-rover-video','User supplied image + bob 2026-10-10 23.22.05.mp4',wheels,.42);fs.writeFileSync(new URL('reference-rover-source.json',out),JSON.stringify(reports[0],null,2));
